      "arFull": "هُوَ الَّذِیْ یُسَیِّرُكُمْ فِی الْبَرِّ وَالْبَحْرِ ؕ حَتّٰۤی اِذَا كُنْتُمْ فِی الْفُلْكِ ۚ وَجَرَیْنَ بِهِمْ بِرِیْحٍ طَیِّبَةٍ وَّفَرِحُوْا بِهَا جَآءَتْهَا رِیْحٌ عَاصِفٌ وَّجَآءَهُمُ الْمَوْجُ مِنْ كُلِّ مَكَانٍ وَّظَنُّوْۤا اَنَّهُمْ اُحِیْطَ بِهِمْ ۙ دَعَوُا اللّٰهَ مُخْلِصِیْنَ لَهُ الدِّیْنَ ۚ۬ لَىِٕنْ اَنْجَیْتَنَا مِنْ هٰذِهٖ لَنَكُوْنَنَّ مِنَ الشّٰكِرِیْنَ ۟",
