      "number": 30,
      "arFull": "هُنَالِكَ تَبْلُوْا كُلُّ نَفْسٍ مَّاۤ اَسْلَفَتْ وَرُدُّوْۤا اِلَی اللّٰهِ مَوْلٰىهُمُ الْحَقِّ وَضَلَّ عَنْهُمْ مَّا كَانُوْا یَفْتَرُوْنَ ۟۠",
      "ur": "اس مقام پر ہر شخص اپنے اگلے کیے ہوئے کاموں کی جانچ کرلے گا [1] اور یہ لوگ اللہ کی طرف جو ان کا مالک حقیقی ہے لوٹائے جائیں گے اور جو کچھ جھوٹ باندھا کرتے تھے سب ان سے غائب ہوجائیں گے.[2]",
      "en": "There, [on that Day], every soul will be put to trial for what it did previously, and they will be returned to Allāh, their master, the Truth, and lost from them is whatever they used to invent.",
