      "number": 49,
      "arFull": "قُلْ لَّاۤ اَمْلِكُ لِنَفْسِیْ ضَرًّا وَّلَا نَفْعًا اِلَّا مَا شَآءَ اللّٰهُ ؕ لِكُلِّ اُمَّةٍ اَجَلٌ ؕ اِذَا جَآءَ اَجَلُهُمْ فَلَا یَسْتَاْخِرُوْنَ سَاعَةً وَّلَا یَسْتَقْدِمُوْنَ ۟",
      "ur": "آپ فرما دیجئے کہ میں اپنی ذات کے لیے تو کسی نفع کا اور کسی ضرر کا اختیار رکھتا ہی نہیں مگر جتنا اللہ کو منظور ہو۔ ہر امت کے لیے ایک معین وقت ہے جب ان کا وه معین وقت آپہنچتا ہے تو ایک گھڑی نہ پیچھے ہٹ سکتے ہیں اور نہ آگے سرک سکتے ہیں.[1]",
      "en": "Say, \"I possess not for myself any harm or benefit except what Allāh should will. For every nation is a [specified] term. When their time has come, then they will not remain behind an hour, nor will they precede [it].\"",
