      "arFull": "وَیَسْتَنْۢبِـُٔوْنَكَ اَحَقٌّ هُوَ ؔؕ قُلْ اِیْ وَرَبِّیْۤ اِنَّهٗ لَحَقٌّ ؔؕۚ وَمَاۤ اَنْتُمْ بِمُعْجِزِیْنَ ۟۠",
